function ensureNewModules(){
  if(!Array.isArray(db.deliveryChallans))db.deliveryChallans=[];
  if(!Array.isArray(db.warranties))db.warranties=[];
  if(!Array.isArray(db.cctvProjects))db.cctvProjects=[];
}
ensureNewModules();

function customerOptions(selected=''){
  return '<option value="">-- Select Customer --</option>'+db.customers.map((p,i)=>`<option value="${i}" ${String(selected)===String(i)?'selected':''}>${esc(p.name||'')}</option>`).join('');
}
function fillCustomer(prefix,idx){
  const p=db.customers[Number(idx)]||{};
  if($(prefix+'_customer'))$(prefix+'_customer').value=p.name||'';
  if($(prefix+'_phone'))$(prefix+'_phone').value=p.phone||'';
  if($(prefix+'_address'))$(prefix+'_address').value=p.address||'';
  if($(prefix+'_location'))$(prefix+'_location').value=p.location||'';
}
