 if(!items.length)return alert('Please add at least one item.');
 const sub=items.reduce((a,x)=>a+x.amount,0),discount=Math.min(Math.max(Number($('#doc_discount')?.value||0),0),sub),taxable=sub-discount,gstPercent=Number($('#doc_gst').value||0),gst=taxable*gstPercent/100,total=taxable+gst;
